package com.trimtime.barber;
import com.trimtime.catalogue.ServiceOffering; import com.trimtime.identity.UserAccount; import jakarta.persistence.*;
@Entity @Table(name="barber_services",uniqueConstraints=@UniqueConstraint(name="uq_barber_service",columnNames={"barber_user_id","service_id"})) public class BarberServiceQualification { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="barber_user_id",nullable=false) private UserAccount barber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="service_id",nullable=false) private ServiceOffering service; protected BarberServiceQualification(){} public BarberServiceQualification(UserAccount barber,ServiceOffering service){this.barber=barber;this.service=service;} public Long getId(){return id;} public UserAccount getBarber(){return barber;} public ServiceOffering getService(){return service;} }
